import pandas as pd
import numpy as np
from scipy import stats

# combine intervene data files that have FWF
frames=[]
for v in ['experiment_1_csv','experiment_3_csv','experiment_4_csv','experiment_5_csv','experiment_6_csv']:
    try:
        df=pd.read_csv(eval(v))
        frames.append(df)
    except Exception as e:
        print(v,'err',e)
big=pd.concat(frames,ignore_index=True)
print(big.columns.tolist())
print(big.shape)
# within each FWF level, does turbidity still predict titer?
if 'FeedWaterFlowRate' in big.columns:
    for lvl,g in big.groupby('FeedWaterFlowRate'):
        if len(g)>5 and g['BrothTurbidity'].std()>0:
            s,i,r,p,se=stats.linregress(g['BrothTurbidity'],g['ProductTiter'])
            print(f"FWF={lvl}: n={len(g)} turb->titer slope={s:.3f} r={r:.3f} p={p:.3g}")

